const codes = ["b10", "B2", "a1", "b2"];
const natural = (x, y) => x.localeCompare(y, "en", { numeric: true });

console.log(codes.toSorted().join(" "));
console.log(codes.toSorted(natural).join(" "));
console.log("á" > "z");
console.log("résumé".localeCompare("resume", "en", { sensitivity: "accent" }) === 0);
